function longestConsecutive(nums) {
  const set = new Set(nums);
  let best = 0;
  for (const x of set) {
    if (!set.has(x - 1)) {
      let curr = x, length = 1;
      while (set.has(curr + 1)) {
        curr++;
        length++;
      }
      best = Math.max(best, length);
    }
  }
  return best;
}

