#include <stdio.h>
#include <stdbool.h>

#define CAP 1024

int slots[CAP];
bool used[CAP];

void setAdd(int v) {
    int i = ((v % CAP) + CAP) % CAP;
    while (used[i] && slots[i] != v) i = (i + 1) % CAP;
    slots[i] = v;
    used[i] = true;
}

bool setHas(int v) {
    int i = ((v % CAP) + CAP) % CAP;
    while (used[i]) {
        if (slots[i] == v) return true;
        i = (i + 1) % CAP;
    }
    return false;
}

int longestConsecutive(int nums[], int n) {
    for (int i = 0; i < n; i++) setAdd(nums[i]);
    int longest = 0;
    for (int i = 0; i < n; i++) {
        int v = nums[i];
        if (!setHas(v - 1)) {
            int count = 1;
            while (setHas(v + count)) count++;
            if (count > longest) longest = count;
        }
    }
    return longest;
}

int main() {
    int nums[] = {100, 4, 200, 1, 3, 2};
    printf("%d\n", longestConsecutive(nums, 6));
    return 0;
}

