using namespace std;
int longestConsecutive(vector<int>&nums) {
    unordered_set<int>s(nums.begin(), nums.end());
    int mx=0;
    for (int n:s)if (!s.count(n-1)) {
        int c=1;
        while (s.count(n+c))c++;
        mx=max(mx, c);
    }
